def q(type,skill,family,prompt,ja,answer,wrong,explain,explainja,*,reading=None,audio=None,order=None,cell=None,check=False):
    n=sum(x['partition']==('check' if check else 'practice') for x in P['questions'])+1
    id=f'U02-{"C" if check else "Q"}{n:02}'
    texts=order or [answer]+[x[0] for x in wrong]
    choices=[dict(id=f'{id}-o{i}',text=t) for i,t in enumerate(texts)]
    correct=[c['id'] for c in choices] if order else [choices[0]['id']]
    reasons={f'{id}-o{i+1}':why for i,(_,why) in enumerate(wrong)}
    if order: reasons={c['id']:'請依「主人＋の＋物品」或本題說明的句子順序排列。' for c in choices}
    offset=n%len(choices);choices=choices[offset:]+choices[:offset]
    kind='order' if order else 'audio' if audio else 'reading' if reading else 'choice'
    teachings=wordcards+(['U02-teach-kanji'] if type in ['T01','T02'] else []) if type in ['T01','T02','T03','T04'] else allteach
    obj=dict(id=id,version='1',unitId='U02',itemId=id,itemFamilyId='U02-'+('CHECK-' if check else 'F-')+(f'listening-{audio:02}' if audio else family),primarySkillId=skill,skillIds=[skill],teachingIds=teachings,partition='check' if check else 'practice',kind=kind,prompt=prompt,promptJa=ja,choices=choices,answer=correct,explanation=explain,explanationJa=explainja,distractorReasons=reasons,hint='先看誰在說話、物品在哪裡，再找主人或關鍵詞。',hintJa='はなすひと、もののばしょ、もちぬしをたしかめよう。',hintPolicy='none' if check else 'practice-only',audioPolicy='required' if audio else 'optional',source='Original authored U02 draft by Codex, 2026-10-30; not official JLPT material',reviewStatus='DRAFT',difficulty=1 if type in ['T01','T02','T03'] else 2)
    if type:obj['typeId']=type
    if reading:obj.update(materialId=R[reading-1][0],material=R[reading-1][1])
    if audio:obj.update(audioId=f'U02-L{audio:02}',audioSrc=f'/assets/audio/u02/listening-{audio:02}.wav')
    if cell is not None:obj['image']={'src':'/assets/img/u02/classroom-contexts.webp','cell':cell,'alt':{'zh':['女孩拿著自己的藍色筆記本。','女孩指著對面男孩手上的紅色鉛筆盒。','兩個孩子指向離兩人都遠的牆上時鐘。','老師手上拿著粉筆，孩子看著老師。'][cell],'ja':['おんなのこが、じぶんのあおいノートをもっています。','おんなのこが、あいてのあかいふでばこをさしています。','ふたりが、とおくのとけいをさしています。','せんせいがチョークをもっています。'][cell]}}
    P['questions'].append(obj)
